create or replace function private.aios_validate_approval_integrity() returns trigger language plpgsql security definer set search_path = '' as $$ declare ag public.aios_agents; tk public.aios_tasks; inv public.aios_tool_invocations; begin if new.invocation_id is not null then select * into inv from public.aios_tool_invocations where id=new.invocation_id; if inv.id is null or inv.organization_id<>new.organization_id then raise exception 'approval invocation organization mismatch' using errcode='23514'; end if; if new.agent_id is not null and inv.agent_id is distinct from new.agent_id then raise exception 'approval agent mismatch' using errcode='23514'; end if; if new.task_id is not null and inv.task_id is distinct from new.task_id then raise exception 'approval task mismatch' using errcode='23514'; end if; if new.tool_key is not null and new.tool_key is distinct from inv.tool_key then raise exception 'approval tool mismatch' using errcode='23514'; end if; if new.arguments_hash is not null and new.arguments_hash is distinct from inv.arguments_hash then raise exception 'approval argument hash mismatch' using errcode='23514'; end if; if new.approval_version is not null and inv.authorization_version is not null and new.approval_version is distinct from inv.authorization_version then raise exception 'approval authorization version mismatch' using errcode='23514'; end if; end if; if new.agent_id is not null then select * into ag from public.aios_agents where id=new.agent_id; if ag.id is null or ag.organization_id<>new.organization_id then raise exception 'approval agent organization mismatch' using errcode='23514'; end if; end if; if new.task_id is not null then select * into tk from public.aios_tasks where id=new.task_id; if tk.id is null or tk.organization_id<>new.organization_id then raise exception 'approval task organization mismatch' using errcode='23514'; end if; end if; return new; end $$;
